import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.DC2M1AAK.js";const p=JSON.parse('{"title":"ADR NNNN — &lt;Decision title>","description":"","frontmatter":{},"headers":[],"relativePath":"reference/adr/template.md","filePath":"reference/adr/template.md"}'),n={name:"reference/adr/template.md"};function r(s,e,l,c,h,d){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-nnnn-—-lt-decision-title" tabindex="-1">ADR NNNN — &lt;Decision title&gt; <a class="header-anchor" href="#adr-nnnn-—-lt-decision-title" aria-label="Permalink to &quot;ADR NNNN — &amp;lt;Decision title&gt;&quot;">​</a></h1><ul><li><strong>Status:</strong> Proposed | Accepted (ratified by &lt;owner&gt;, &lt;date&gt;) | Superseded by NNNN</li><li><strong>Date:</strong> &lt;date&gt;</li><li><strong>Roadmap:</strong> which items this gates / is gated by</li><li><strong>Deciders:</strong> &lt;owner&gt;</li></ul><h2 id="_1-context" tabindex="-1">1. Context <a class="header-anchor" href="#_1-context" aria-label="Permalink to &quot;1. Context&quot;">​</a></h2><p>What the system does today (concrete file paths), what is changing, and the exact question this ADR settles: <em>&quot;The question this ADR settles: …&quot;</em></p><h2 id="_2-decision-drivers" tabindex="-1">2. Decision drivers <a class="header-anchor" href="#_2-decision-drivers" aria-label="Permalink to &quot;2. Decision drivers&quot;">​</a></h2><p>Numbered, concrete, ranked.</p><h2 id="_3-options-considered" tabindex="-1">3. Options considered <a class="header-anchor" href="#_3-options-considered" aria-label="Permalink to &quot;3. Options considered&quot;">​</a></h2><p>For each: one-line mechanism, then + and − bullets. Always include &quot;do the simplest thing&quot; and say honestly where it stops scaling.</p><h2 id="_4-decision" tabindex="-1">4. Decision <a class="header-anchor" href="#_4-decision" aria-label="Permalink to &quot;4. Decision&quot;">​</a></h2><p>Name the option. The concrete rules, numbered, each enforceable. End with a <strong>one-line rule for the team</strong> — if it cannot be compressed to one line, it is not crisp enough yet.</p><h2 id="_5-the-convention-this-creates" tabindex="-1">5. The convention this creates <a class="header-anchor" href="#_5-the-convention-this-creates" aria-label="Permalink to &quot;5. The convention this creates&quot;">​</a></h2><p>The file/package layout or contract other work implements against (an actual tree or shape).</p><h2 id="_6-migration-from-today" tabindex="-1">6. Migration from today <a class="header-anchor" href="#_6-migration-from-today" aria-label="Permalink to &quot;6. Migration from today&quot;">​</a></h2><p>Today → After per moving part; say what does NOT change.</p><h2 id="_7-consequences" tabindex="-1">7. Consequences <a class="header-anchor" href="#_7-consequences" aria-label="Permalink to &quot;7. Consequences&quot;">​</a></h2><p>Positive / costs accepted (with mitigations) / neutral follow-ups.</p><h2 id="_8-what-this-unblocks" tabindex="-1">8. What this unblocks <a class="header-anchor" href="#_8-what-this-unblocks" aria-label="Permalink to &quot;8. What this unblocks&quot;">​</a></h2><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/adr/TEMPLATE.md">docs/adr/TEMPLATE.md</a> — edit it there; the site mirrors the repository.</small></p>',19)])])}const u=t(n,[["render",r]]);export{p as __pageData,u as default};
